=head2 Google::Storage::Control::V2::StorageControl::RenameFolderRequest

Request message for RenameFolder. This operation is only applicable to a
hierarchical namespace enabled bucket.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Required. Name of the source folder being renamed.
Format: `projects/{project}/buckets/{bucket}/folders/{folder}`

=item * C<< $msg->destination_folder_id() >> / C<< $msg->destination_folder_id($value) >>

Type: C<String>

Required. The destination folder ID, e.g. `foo/bar/`.

=item * C<< $msg->if_metageneration_match() >> / C<< $msg->if_metageneration_match($value) >>

Type: C<Int64>

Makes the operation only succeed conditional on whether the source
folder's current metageneration matches the given value.

=item * C<< $msg->if_metageneration_not_match() >> / C<< $msg->if_metageneration_not_match($value) >>

Type: C<Int64>

Makes the operation only succeed conditional on whether the source
folder's current metageneration does not match the given value.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. A unique identifier for this request. UUID is the recommended
format, but other formats are still accepted. This request is only
idempotent if a `request_id` is provided.

=back

