Identifier. The resource name of `IntelligenceFinding`.
Format:
`projects/{project}/locations/{location}/intelligenceFindings/{intelligence_finding}`

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Output only. A short description about the finding.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Storage::Control::V2::FindingType>)

Output only. Type of this finding.

=item * C<< $msg->category() >> / C<< $msg->category($value) >>

Type: C<Enum> (L<Google::Storage::Control::V2::FindingCategory>)

Output only. Category of this finding.

=item * C<< $msg->severity() >> / C<< $msg->severity($value) >>

Type: C<Enum> (L<Google::Storage::Control::V2::FindingSeverity>)

